import pytest

from string_utils import slugify


def test_slugify_basic_lowercasing():
    assert slugify("Hello World") == "hello-world"


def test_slugify_consecutive_spaces_collapse():
    assert slugify("hello   world") == "hello-world"


def test_slugify_mixed_special_chars_collapse():
    assert slugify("hello!@#world") == "hello-world"


def test_slugify_leading_special_stripped():
    assert slugify("!!!hello") == "hello"


def test_slugify_trailing_special_stripped():
    assert slugify("hello!!!") == "hello"


def test_slugify_single_char_alnum():
    assert slugify("A") == "a"


def test_slugify_single_char_special():
    assert slugify("!") == ""


def test_slugify_numbers_with_special():
    assert slugify("123-456") == "123-456"


def test_slugify_underscore_is_special():
    assert slugify("hello_world") == "hello-world"


def test_slugify_tab_and_newline_collapse():
    assert slugify("hello\t\nworld") == "hello-world"

