import pytest

from string_utils import mask_email


def test_mask_email_single_char_local():
    assert mask_email("z@test.io") == "z@test.io"


def test_mask_email_two_char_local():
    assert mask_email("zz@test.io") == "z*@test.io"


def test_mask_email_missing_at_raises():
    with pytest.raises(ValueError):
        mask_email("plainstring")


def test_mask_email_empty_local_raises():
    with pytest.raises(ValueError):
        mask_email("@host.com")


def test_mask_email_empty_domain_raises():
    with pytest.raises(ValueError):
        mask_email("user@")


def test_mask_email_empty_string_raises():
    with pytest.raises(ValueError):
        mask_email("")


def test_mask_email_local_preserves_first_char():
    assert mask_email("x9y@dom.net") == "x**@dom.net"


def test_mask_email_domain_with_subdomains():
    assert mask_email("ab@sub.domain.co.uk") == "a*@sub.domain.co.uk"


def test_mask_email_long_local_masked_correctly():
    local = "abcdefghij"
    expected = "a" + "*" * 9 + "@ex.com"
    assert mask_email(f"{local}@ex.com") == expected

