import pytest

from date_utils import is_leap_year


def test_is_leap_year_divisible_by_4_not_century():
    assert is_leap_year(2020) is True


def test_is_leap_year_century_divisible_by_400():
    assert is_leap_year(2000) is True


def test_is_leap_year_century_not_divisible_by_400():
    assert is_leap_year(1800) is False


def test_is_leap_year_not_divisible_by_4():
    assert is_leap_year(1999) is False


def test_is_leap_year_year_zero():
    # 0 is divisible by 4, 100, and 400 -> leap year
    assert is_leap_year(0) is True


def test_is_leap_year_negative_year_divisible_by_400():
    # -400 is divisible by 4, 100, and 400 -> leap year
    assert is_leap_year(-400) is True


def test_is_leap_year_negative_year_century_not_div_400():
    # -300 is divisible by 4 and 100, but not by 400 -> not leap
    assert is_leap_year(-300) is False


def test_is_leap_year_large_leap_year():
    assert is_leap_year(4000) is True


def test_is_leap_year_large_non_leap_century():
    assert is_leap_year(3900) is False

