import pytest

from containers import most_frequent


def test_most_frequent_empty_raises():
    with pytest.raises(ValueError, match="empty input"):
        most_frequent([])


def test_most_frequent_single_element():
    assert most_frequent([42]) == 42


def test_most_frequent_all_distinct_returns_first():
    # All elements appear once; first occurrence should win
    assert most_frequent(["x", "y", "z"]) == "x"


def test_most_frequent_tie_broken_by_first_occurrence():
    # "a" and "b" both appear twice; "a" appears first
    assert most_frequent(["a", "b", "b", "a"]) == "a"


def test_most_frequent_unique_max_frequency():
    # "c" appears 3 times, others appear once
    assert most_frequent(["c", "a", "c", "b", "c"]) == "c"


def test_most_frequent_numeric_values():
    assert most_frequent([1, 2, 2, 3, 3, 3]) == 3


def test_most_frequent_mixed_hashable_types():
    # Integers, strings, and tuples are all hashable
    items = [1, "a", (1, 2), 1, "a", (1, 2), (1, 2)]
    assert most_frequent(items) == (1, 2)


def test_most_frequent_negative_numbers():
    assert most_frequent([-1, -2, -1, -3, -1]) == -1


def test_most_frequent_boolean_values():
