import pytest

from parsers import parse_csv_line


def test_empty_string_returns_single_empty_field():
    """An empty line should yield a list with one empty string."""
    assert parse_csv_line("") == [""]


def test_single_character_field():
    """A single character without quotes yields that character."""
    assert parse_csv_line("a") == ["a"]


def test_single_quoted_character():
    """A single quoted character yields that character."""
    assert parse_csv_line('"a"') == ["a"]


def test_two_fields_simple():
    """Two simple unquoted fields."""
    assert parse_csv_line("a,b") == ["a", "b"]


def test_field_with_comma_inside_quotes_only():
    """Comma inside quotes is part of the field."""
    assert parse_csv_line('"a,b"') == ["a,b"]


def test_escaped_quote_produces_single_quote():
    """Two consecutive quotes inside a quoted field produce one literal quote."""
    assert parse_csv_line('"a""b"') == ['a"b']


def test_escaped_quote_only_field():
    """A field containing only an escaped quote."""
    assert parse_csv_line('""""') == ['"']


def test_trailing_comma():
    """Trailing comma produces an empty last field."""
    assert parse_csv_line("a,") == ["a", ""]


def test_leading_comma():
    """Leading comma produces an empty first field."""
    assert parse_csv_line(",a") == ["", "a"]


def test_only_commas():
    """Only commas produces empty fields."""
    assert parse_csv_line(",,") == ["", "", ""]


def test_quoted_empty_field():
    """Quoted empty field."""
    assert parse_csv_line('""') == [""]


def test_quoted_empty_field_among_others():
    """Quoted empty field among other fields."""
    assert parse_csv_line('a,"",b') == ["a", "", "b"]


def test_multiple_escaped_quotes():
    """Multiple escaped quotes in one field."""
    assert parse_csv_line('"a""b""c""d"') == ['a"b"c"d']


def test_escaped_quote_with_comma():
    """Field with both comma and escaped quote inside quotes."""
    assert parse_csv_line('"x,y""z"') == ['x,y"z']


def test_consecutive_quoted_fields():
    """Two consecutive quoted fields."""
    assert parse_csv_line('"a","b"') == ["a", "b"]


def test_mixed_quoted_unquoted():
    """Mix of quoted and unquoted fields."""
    assert parse_csv_line('plain,"quoted",another') == ["plain", "quoted", "another"]


def test_quoted_field_with_leading_trailing_spaces():
    """Spaces inside quotes are preserved."""
    assert parse_csv_line('" hello ",world') == [" hello ", "world"]


def test_unquoted_field_with_spaces():
    """Spaces in unquoted fields are preserved."""
    assert parse_csv_line("hello world,foo") == ["hello world", "foo"]


def test_large_number_of_fields():
    """Many fields parsed correctly."""
    n = 50
    line = ",".join(["f" + str(i) for i in range(n)])
    expected = ["f" + str(i) for i in range(n)]
    assert parse_csv_line(line) == expected


def test_quoted_field_with_tab():
    """Tab character inside quoted field is preserved."""
    assert parse_csv_line('"a\tb",c') == ["a\tb", "c"]


def test_quoted_field_with_unicode():
    """Unicode characters inside quoted field are preserved."""
    assert parse_csv_line('"héllo",wörld') == ["héllo", "wörld"]

