import pytest

from parsers import parse_kv_pairs


def test_kv_basic():
    """Basic parsing of multiple key-value pairs."""
    assert parse_kv_pairs("a=1,b=2") == {"a": "1", "b": "2"}


def test_kv_empty_input():
    """Empty string returns empty dict."""
    assert parse_kv_pairs("") == {}


def test_kv_whitespace_input():
    """Whitespace-only string returns empty dict."""
    assert parse_kv_pairs("   ") == {}


def test_kv_single_entry():
    """Single key-value pair."""
    assert parse_kv_pairs("key=value") == {"key": "value"}


def test_kv_strips_whitespace():
    """Leading/trailing whitespace on keys and values is stripped."""
    assert parse_kv_pairs("  k1  =  v1  ,  k2 = v2  ") == {"k1": "v1", "k2": "v2"}


def test_kv_empty_value():
    """Value can be empty."""
    assert parse_kv_pairs("key=") == {"key": ""}


def test_kv_empty_key():
    """Key can be empty (after stripping)."""
    assert parse_kv_pairs("=value") == {"": "value"}


def test_kv_equals_in_value():
    """Only the first '=' is used to split; rest stays in value."""
    assert parse_kv_pairs("url=http://example.com?a=1&b=2") == {"url": "http://example.com?a=1&b=2"}


def test_kv_missing_equals_raises():
    """Entry without '=' raises ValueError."""
    with pytest.raises(ValueError):
        parse_kv_pairs("a=1,bad_entry")


def test_kv_all_entries_missing_equals_raises():
    """If no entry has '=', ValueError is raised."""
    with pytest.raises(ValueError):
        parse_kv_pairs("abc,def")


def test_kv_trailing_comma():
    """Trailing comma creates an empty entry which lacks '=' and raises."""
    with pytest.raises(ValueError):
        parse_kv_pairs("a=1,")


def test_kv_leading_comma():
    """Leading comma creates an empty entry which lacks '=' and raises."""
    with pytest.raises(ValueError):
        parse_kv_pairs(",a=1")


def test_kv_consecutive_commas():
    """Consecutive commas create empty entries which lack '=' and raise."""
    with pytest.raises(ValueError):
